{"source":"#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
	int n,k,l,c,d,p,nl,np,fatias,toast=0,rodada,rodadasal;
	scanf("%d %d %d %d %d %d %d %d",&n,&k,&l,&c,&d,&p,&nl,&np);
	fatias = c * d;
	l = k * l;
	rodada = n * nl;
	rodadasal = n * np;
	while(l >= rodada && fatias >= n && p >= rodadasal)
	{
		l = l - rodada;
		fatias = fatias - n;
		p = p - rodadasal;
		toast++;
	}
	printf("%i\n",toast);
	return 0;
}
